learning_path:
{
  "path": [
    {
      "step": 1,
      "course_id": "COU6164",
      "rationale": "Foundational course on leadership, covering team building, communication, negotiation, transparency, and collaboration."
    },
    {
      "step": 2,
      "course_id": "COU1890",
      "rationale": "Builds on the foundational course, focusing on challenges of leading technical teams, communication, recruiting, applying vision, engaging teams, and asking questions."
    },
    {
      "step": 3,
      "course_id": "COU3465",
      "rationale": "Develops self-awareness, trust in relationships, ethical decision-making, leadership development, and defining leadership, building on the previous courses."
    },
    {
      "step": 4,
      "course_id": "COU3768",
      "rationale": "Covers business communication, coaching, strategy, team management, and leadership and management, integrating the previous courses' concepts."
    },
    {
      "step": 5,
      "course_id": "COU3556",
      "rationale": "Introduces process improvement, leadership, statistical analysis and tools, six sigma, team roles and responsibilities, and leadership development, applying the previous courses' knowledge."
    },
    {
      "step": 6,
      "course_id": "COU4352",
      "rationale": "Develops team building, leadership, management, coaching, and team management skills, integrating the previous courses' concepts and applying them to real-world scenarios."
    },
    {
      "step": 7,
      "course_id": "COU4080",
      "rationale": "Fosters goal setting, coaching, storytelling, influence, and collaboration skills, building on the previous courses and promoting a growth mindset."
    },
    {
      "step": 8,
      "course_id": "COU4681",
      "rationale": "Covers team building, emotional intelligence, team management, systems thinking, and leadership and management, integrating the previous courses' concepts and promoting self-awareness and accountability."
    },
    {
      "step": 9,
      "course_id": "COU5977",
      "rationale": "Develops relationship management, professional development, communication skills, conflict resolution, and leadership skills, applying the previous courses' knowledge and promoting a growth mindset."
    },
    {
      "step": 10,
