      "step": 2,
      "course_id": "EDX1775",
      "rationale": "Building on the algebra and trigonometry skills, this course covers kinematics, work and energy, momentum and collisions, and conservation laws."
    },
    {
      "step": 3,
      "course_id": "EDX3022",
      "rationale": "This course covers the principles of mechanics, including rotational motion, torque, and static equilibrium, which are essential for advanced physics."
    },
    {
      "step": 4,
      "course_id": "EDX2227",
      "rationale": "This course provides a comprehensive review of rotational motion, including torque, rotational kinematics, and angular momentum, which are crucial for advanced physics."
    },
